/**
 * @file src/ui/scheduleTooltipHelpers.ts
 * Shared helpers for #customTooltip via game.scheduleTooltip.
 */

import type { GameRuntime } from '../types/game.js';

type GameTooltipHost = GameRuntime & {
  scheduleTooltip?: (event: MouseEvent | Event, title: string, description: string, delayMs: number) => void;
  scheduleTooltipAutoHide?: (delayMs?: number) => void;
  hideTooltip?: () => void;
  isTouchUi?: () => boolean;
};

export type TapTooltipEvent = {
  clientX: number;
  clientY: number;
  target: Element;
  currentTarget: Element;
};

function getGame(): GameTooltipHost | null {
  return (globalThis as { game?: GameTooltipHost }).game ?? null;
}

export function buildTapTooltipEvent(sourceEvent: MouseEvent, element: Element): TapTooltipEvent {
  const rect = element.getBoundingClientRect();
  const fallbackX = rect.left + (rect.width / 2);
  const fallbackY = rect.top + (rect.height / 2);
  const x = (sourceEvent && typeof sourceEvent.clientX === 'number') ? sourceEvent.clientX : fallbackX;
  const y = (sourceEvent && typeof sourceEvent.clientY === 'number') ? sourceEvent.clientY : fallbackY;
  return {
    clientX: x,
    clientY: y,
    target: element,
    currentTarget: element,
  };
}

export function normalizeTooltipEvent(
  el: HTMLElement,
  event: MouseEvent | FocusEvent,
): MouseEvent | FocusEvent | { clientX: number; clientY: number; currentTarget?: HTMLElement } {
  if ('clientX' in event && typeof event.clientX === 'number' && typeof event.clientY === 'number') {
    return event;
  }
  const rect = el.getBoundingClientRect();
  return { clientX: rect.left + (rect.width / 2), clientY: rect.top + 6, currentTarget: el };
}

export type TooltipPlacement = 'pointer' | 'touchCenter' | 'anchorLeft';

export type TooltipPositionOffsets = {
  anchorGap?: number;
  pointerGap?: number;
};

export const MILTANK_FARM_TOOLTIP_VARIANT = 'miltank-farm';

export function positionCustomTooltip(
  tooltip: HTMLElement,
  mode: TooltipPlacement,
  pointer?: { x: number; y: number },
  margin = 12,
  anchor?: Element | null,
  offsets?: TooltipPositionOffsets,
): void {
  const anchorGap = offsets?.anchorGap ?? 8;
  const pointerGap = offsets?.pointerGap ?? 15;
  tooltip.style.transform = 'none';
  tooltip.style.bottom = '';
  tooltip.style.right = '';

  if (mode === 'touchCenter') {
    const w = tooltip.offsetWidth;
    const h = tooltip.offsetHeight;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const left = Math.max(margin, Math.min((vw - w) / 2, vw - w - margin));
    const top = Math.max(margin, Math.min((vh - h) / 2, vh - h - margin));
    tooltip.style.left = `${left}px`;
    tooltip.style.top = `${top}px`;
    return;
  }

  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const tw = tooltip.offsetWidth || 280;
  const th = tooltip.offsetHeight || 80;

  let left: number;
  let top: number;

  if (mode === 'anchorLeft' && anchor) {
    const rect = anchor.getBoundingClientRect();
    left = rect.left - tw - anchorGap;
    top = rect.top + (rect.height / 2) - (th / 2);
    if (left < margin) {
      left = Math.max(margin, rect.right - tw);
    }
    if (top + th > vh - margin) {
      top = Math.max(margin, rect.top - th - anchorGap);
    }
    if (top < margin) {
      top = Math.min(vh - th - margin, rect.bottom + anchorGap);
    }
  } else {
    left = (pointer?.x ?? 0) + pointerGap;
    top = (pointer?.y ?? 0) + pointerGap;
    if (left + tw > vw - margin) {
      left = Math.max(margin, (pointer?.x ?? left) - tw - pointerGap);
    }
    if (top + th > vh - margin) {
      const above = (pointer?.y ?? top) - th - pointerGap;
      top = above >= margin ? above : vh - th - margin;
    }
  }

  left = Math.max(margin, Math.min(left, vw - tw - margin));
  top = Math.max(margin, Math.min(top, vh - th - margin));

  tooltip.style.left = `${left}px`;
  tooltip.style.top = `${top}px`;
}

export function showGameTooltip(
  event: MouseEvent | FocusEvent,
  title: string,
  body = '',
  delayMs = 50,
): void {
  const g = getGame();
  if (!g?.scheduleTooltip) return;
  const anchor = (event.currentTarget instanceof HTMLElement)
    ? event.currentTarget
    : null;
  const tooltipEvent = anchor ? normalizeTooltipEvent(anchor, event) : event;
  g.scheduleTooltip(tooltipEvent, title, body, delayMs);
  if (g.isTouchUi?.() && g.scheduleTooltipAutoHide) {
    g.scheduleTooltipAutoHide();
  }
}

export function hideGameTooltip(): void {
  getGame()?.hideTooltip?.();
}

export type TooltipContent = { title: string; body?: string };

export function miltankFarmTooltipHandlers(
  getContent: () => TooltipContent,
): ReturnType<typeof touchTooltipHandlers> {
  return touchTooltipHandlers(getContent);
}

export function touchTooltipHandlers(
  getContent: () => TooltipContent,
): {
  onmouseenter: (e: MouseEvent | FocusEvent) => void;
  onmouseleave: () => void;
  onfocus: (e: MouseEvent | FocusEvent) => void;
  onblur: () => void;
  onclick: (e: MouseEvent) => void;
  onkeydown: (e: KeyboardEvent) => void;
} {
  const show = (e: MouseEvent | FocusEvent) => {
    const { title, body = '' } = getContent();
    showGameTooltip(e, title, body);
  };
  const showTap = (e: MouseEvent) => {
    const g = getGame();
    if (!g?.isTouchUi?.()) return;
    e.stopPropagation();
    const { title, body = '' } = getContent();
    showGameTooltip(e, title, body);
  };
  return {
    onmouseenter: show,
    onmouseleave: hideGameTooltip,
    onfocus: show,
    onblur: hideGameTooltip,
    onclick: showTap,
    onkeydown: (e: KeyboardEvent) => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      e.preventDefault();
      if (e.currentTarget instanceof HTMLElement) {
        e.currentTarget.click();
      }
    },
  };
}

export function bindGameTooltip(
  el: HTMLElement | null,
  datasetKey: string,
  getContent: (game: GameRuntime) => { title: string; body?: string },
): void {
  if (!el || el.dataset[datasetKey]) return;
  const show = function (this: HTMLElement, event: MouseEvent | FocusEvent) {
    const g = getGame();
    if (!g?.scheduleTooltip) return;
    const { title, body = '' } = getContent(g);
    g.scheduleTooltip(normalizeTooltipEvent(this, event), title, body, 50);
    if (g.isTouchUi?.() && g.scheduleTooltipAutoHide) {
      g.scheduleTooltipAutoHide();
    }
  };
  const showTap = function (this: HTMLElement, event: MouseEvent) {
    const g = getGame();
    if (!g?.isTouchUi?.()) return;
    event.stopPropagation();
    const { title, body = '' } = getContent(g);
    g.scheduleTooltip(buildTapTooltipEvent(event, this), title, body, 50);
    if (g.scheduleTooltipAutoHide) {
      g.scheduleTooltipAutoHide(1400);
    }
  };
  const hide = () => hideGameTooltip();
  el.removeAttribute('title');
  el.addEventListener('mouseenter', show);
  el.addEventListener('mouseleave', hide);
  el.addEventListener('focus', show);
  el.addEventListener('blur', hide);
  el.addEventListener('click', showTap);
  el.dataset[datasetKey] = '1';
}
